// This file was generated by Slater.app - SVG CMS.js


document.querySelectorAll('.icon-svg').forEach(img => {
  const imgID = img.id;
  const imgClass = img.className;
  const imgURL = img.src;

  fetch(imgURL)
    .then(res => res.text())
    .then(data => {
      const parser = new DOMParser();
      const svgDoc = parser.parseFromString(data, 'image/svg+xml');
      const svg = svgDoc.querySelector('svg');

      if (imgID) svg.id = imgID;
      if (imgClass) svg.setAttribute('class', imgClass + ' replaced-svg');

      // Supprime les couleurs fixes pour laisser place au CSS
      svg.removeAttribute('xmlns:a');
      img.parentNode.replaceChild(svg, img);
    });
});


